    "content": "const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface Supplier {
  supplierId: number;
  companyId: number;
  supplierName: string;
  contactName?: string;
  phone?: string;
  email?: string;
  address?: string;
  active: string; // '1' or '0'
  created_At: string;
  updated_at?: string;
}

export interface SupplierListResponse {
  suppliers: Supplier[];
}

// GET ALL — POST /all_suppliers
export async function getAllSuppliers(companyId: number): Promise<Supplier[]> {
  const res = await fetch(BASE_URL + "/all_suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "companyId": companyId }] })
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data: SupplierListResponse = await res.json();
  return data.suppliers ?? [];
}

// CREATE — action: 1
export async function createSupplier(payload: Omit<Supplier, "supplierId" | "created_At" | "updated_at">): Promise<Supplier> {
  const res = await fetch(BASE_URL + "/suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "action": 1, ...payload }] })
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  return await res.json();
}

// UPDATE — action: 2
export async function updateSupplier(supplierId: number, payload: Partial<Omit<Supplier, "supplierId" | "created_At" | "updated_at" | "companyId">>): Promise<Supplier> {
  const res = await fetch(BASE_URL + "/suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "action": 2, "supplierId": supplierId, ...payload }] })
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  return await res.json();
}

// DELETE — action: 3
export async function deleteSupplier(supplierId: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "action": 3, "supplierId": supplierId, "companyId": companyId }] })
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
}
