    "content": "import React, { useState, useEffect } from 'react';
import {
  IonPage,
  IonContent,
  IonList,
  IonItem,
  IonLabel,
  IonButton,
  IonIcon,
  IonModal,
  IonInput,
  IonToggle,
  IonLoading,
  IonToast,
  IonFab,
  IonFabButton,
  IonAlert,
  useIonViewWillEnter,
  IonInfiniteScroll,
  IonInfiniteScrollContent
} from '@ionic/react';
import { add, create, trash, people } from 'ionicons/icons';
import { InputInputEventDetail, ToggleChangeEventDetail } from '@ionic/core'; // Explicit CustomEvent generic types

import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../contexts/UserContext';
import {
  Supplier,
  getAllSuppliers,
  createSupplier,
  updateSupplier,
  deleteSupplier,
} from '../api/supplierApi';

import './SupplierPage.css';

// UTC to Hermosillo (UTC-7) conversion utility
const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const SupplierPage: React.FC = () => {
  const { companyId, roleCode } = useUser();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentSupplier, setCurrentSupplier] = useState<Supplier | null>(null);
  const [formState, setFormState] = useState<Omit<Supplier, 'supplierId' | 'created_At' | 'updated_at'>>({
    companyId: companyId,
    supplierName: '',
    contactName: '',
    phone: '',
    email: '',
    address: '',
    active: '1',
  });
  const [supplierNameError, setSupplierNameError] = useState<string | undefined>(undefined);

  const [deleteAlert, setDeleteAlert] = useState<{ show: boolean; supplierIdToDelete: number | null }>(
    { show: false, supplierIdToDelete: null }
  );

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const loadSuppliers = async () => {
    setLoading(true);
    setError('');
    try {
      const data = await getAllSuppliers(companyId);
      setSuppliers(data);
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar proveedores.');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    loadSuppliers();
  }, [companyId]);

  useEffect(() => {
    setFormState(prev => ({ ...prev, companyId: companyId }));
  }, [companyId]);

  const handleAddSupplier = () => {
    setIsEditing(false);
    setCurrentSupplier(null);
    setFormState({
      companyId: companyId,
      supplierName: '',
      contactName: '',
      phone: '',
      email: '',
      address: '',
      active: '1',
    });
    setSupplierNameError(undefined);
    setShowModal(true);
  };

  const handleEditSupplier = (supplier: Supplier) => {
    setIsEditing(true);
    setCurrentSupplier(supplier);
    setFormState({
      companyId: supplier.companyId,
      supplierName: supplier.supplierName,
      contactName: supplier.contactName || '',
      phone: supplier.phone || '',
      email: supplier.email || '',
      address: supplier.address || '',
      active: supplier.active,
    });
    setSupplierNameError(undefined);
    setShowModal(true);
  };

  const handleDeleteSupplier = async (supplierId: number) => {
    setDeleteAlert({ show: true, supplierIdToDelete: supplierId });
  };

  const confirmDelete = async () => {
    if (deleteAlert.supplierIdToDelete !== null) {
      setLoading(true);
      setError('');
      try {
        await deleteSupplier(deleteAlert.supplierIdToDelete, companyId);
        setSuppliers(suppliers.filter((s) => s.supplierId !== deleteAlert.supplierIdToDelete));
        setDeleteAlert({ show: false, supplierIdToDelete: null });
        setError('Proveedor eliminado exitosamente.'); // Using error toast for success message per prompt
      } catch (err) {
        setError((err as Error).message ?? 'Error al eliminar proveedor.');
      } finally {
        setLoading(false);
      }
    }
  };

  const validateForm = () => {
    let valid = true;
    if (!formState.supplierName.trim()) {
      setSupplierNameError('El nombre del proveedor es requerido.');
      valid = false;
    } else {
      setSupplierNameError(undefined);
    }
    return valid;
  };

  const handleSaveSupplier = async () => {
    if (!validateForm()) {
      return;
    }

    setLoading(true);
    setError('');
    try {
      if (isEditing && currentSupplier) {
        await updateSupplier(currentSupplier.supplierId, formState);
        setSuppliers(suppliers.map((s) => (s.supplierId === currentSupplier.supplierId ? { ...s, ...formState, updated_at: new Date().toISOString() } : s)));
        setError('Proveedor actualizado exitosamente.');
      } else {
        await createSupplier(formState);
        loadSuppliers(); // Re-fetch all to get new item with its ID and created_At date.
        setError('Proveedor creado exitosamente.');
      }
      setShowModal(false);
    } catch (err) {
      setError((err as Error).message ?? `Error al ${isEditing ? 'actualizar' : 'crear'} proveedor.`);
    } finally {
      setLoading(false);
    }
  };

  const loadMoreItems = (ev: CustomEvent<void>) => {
    // Since getAllSuppliers loads all available data for the company, there are no more items to load via pagination.
    // We just complete the infinite scroll event.
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  return (
    <IonPage className="supplier-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Proveedores — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonLoading isOpen={loading} message="Cargando proveedores..." />
        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color={error.toLowerCase().includes('error') ? 'danger' : 'success'}
        />

        <IonList className="supplier-list">
          {suppliers.length === 0 && !loading && !error && (
            <IonItem><IonLabel>No hay proveedores registrados.</IonLabel></IonItem>
          )}
          {suppliers.map((supplier) => (
            <IonItem key={supplier.supplierId} className="supplier-item">
              <IonLabel>
                <h2>{supplier.supplierName}</h2>
                <p>Contacto: {supplier.contactName || 'N/A'}</p>
                <p>Teléfono: {supplier.phone || 'N/A'}</p>
                <p>Email: {supplier.email || 'N/A'}</p>
                <p>Estado: {supplier.active === '1' ? 'Activo' : 'Inactivo'}</p>
                <p>Creado: {toHermosillo(supplier.created_At)}</p>
              </IonLabel>
              <IonButton fill="clear" slot="end" onClick={() => handleEditSupplier(supplier)}>
                <IonIcon icon={create} />
              </IonButton>
              <IonButton fill="clear" slot="end" color="danger" onClick={() => handleDeleteSupplier(supplier.supplierId)}>
                <IonIcon icon={trash} />
              </IonButton>
            </IonItem>
          ))}
          <IonInfiniteScroll onIonInfinite={loadMoreItems}>
            <IonInfiniteScrollContent loadingText="Cargando más proveedores..."></IonInfiniteScrollContent>
          </IonInfiniteScroll>
        </IonList>

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={handleAddSupplier} className="supplier-fab-button">
            <IonIcon icon={add} />
          </IonFabButton>
        </IonFab>

        <IonModal isOpen={showModal} onDidDismiss={() => setShowModal(false)} className="supplier-modal">
          <Header
            presentAlertPopover={presentAlertPopover}
            presentMailPopover={presentMailPopover}
            screenTitle={isEditing ? 'Editar Proveedor' : 'Nuevo Proveedor'}
          />
          <IonContent className="ion-padding supplier-modal-content">
            <div className="supplier-form-fields">
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre del Proveedor *"
                  labelPlacement="floating"
                  value={formState.supplierName}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => {
                    setFormState(p => ({ ...p, supplierName: e.detail.value! }));
                    if (e.detail.value) setSupplierNameError(undefined); else setSupplierNameError('El nombre del proveedor es requerido.');
                  }}
                  className={supplierNameError ? 'ion-invalid ion-touched' : ''}
                  errorText={supplierNameError}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre de Contacto"
                  labelPlacement="floating"
                  value={formState.contactName}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, contactName: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Teléfono"
                  labelPlacement="floating"
                  type="tel"
                  value={formState.phone}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, phone: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Email"
                  labelPlacement="floating"
                  type="email"
                  value={formState.email}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, email: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Dirección"
                  labelPlacement="floating"
                  value={formState.address}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, address: e.detail.value! }))}
                />
              </div>
              <IonItem lines="none" className="supplier-toggle-item">
                <IonLabel>Activo</IonLabel>
                <IonToggle
                  checked={formState.active === '1'}
                  onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => setFormState(p => ({ ...p, active: e.detail.checked ? '1' : '0' }))}
                  slot="end"
                />
              </IonItem>
            </div>

            <IonButton expand="block" className="ion-margin-top" onClick={handleSaveSupplier} disabled={loading}>
              {loading ? <IonSpinner name="crescent" /> : (isEditing ? 'Guardar Cambios' : 'Crear Proveedor')}
            </IonButton>
          </IonContent>
        </IonModal>

        <IonAlert
          isOpen={deleteAlert.show}
          onDidDismiss={() => setDeleteAlert({ show: false, supplierIdToDelete: null })}
          header={'Confirmar eliminación'}
          message={'¿Estás seguro de que quieres eliminar este proveedor? Esta acción no se puede deshacer.'}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: confirmDelete, cssClass: 'danger' },
          ]}
        />
      </IonContent>
    </IonPage>
  );
};

export default SupplierPage;
